module cheapest_price (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [11:0] mag_data [3:0],\n    input wire [1:0]  mag_len  [3:0],\n    output reg [3:0]  result_digits [11:0],\n    output reg [3:0]  result_len,\n    output reg        result_valid\n);\n\n    // State definitions\n    localparam [3:0] S_IDLE = 4'd0;\n    localparam [3:0] S_LOAD = 4'd1;\n    localparam [3:0] S_COMB_START = 4'd2;\n    localparam [3:0] S_COMB_SELECT = 4'd3;\n    localparam [3:0] S_SORT = 4'd4;\n    localparam [3:0] S_CONCAT = 4'd5;\n    localparam [3:0] S_COMPARE = 4'd6;\n    localparam [3:0] S_UPDATE = 4'd7;\n    localparam [3:0] S_NEXT_COMB = 4'd8;\n    localparam [3:0] S_DONE = 4'd9;\n\n    reg [3:0] state, next_state;\n\n    // Magnet storage\n    reg [11:0] orig_data [0:3];\n    reg [1:0]  orig_len  [0:3];\n    reg [11:0] flip_data [0:3];\n    reg [1:0]  flip_len  [0:3];\n    reg        flip_valid[0:3];\n\n    reg [3:0]  sel_data  [0:3];\n    reg [1:0]  sel_len   [0:3];\n    reg [3:0]  sorted_data[0:3];\n    reg [1:0]  sorted_len [0:3];\n    reg [3:0]  cand_digits[0:11];\n    reg [3:0]  cand_len;\n    reg [3:0]  best_digits[0:11];\n    reg [3:0]  best_len;\n    reg        best_valid;\n    reg [3:0]  comb;\n    integer i, j, k;\n\n    // FSM\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n            result_valid <= 1'b0;\n            best_valid <= 1'b0;\n            comb <= 4'd0;\n            for (i = 0; i < 4; i = i + 1) begin\n                orig_data[i] <= 12'd0;\n                orig_len[i] <= 2'd0;\n                flip_data[i] <= 12'd0;\n                flip_len[i] <= 2'd0;\n                flip_valid[i] <= 1'b0;\n            end\n            for (i = 0; i < 12; i = i + 1) begin\n                cand_digits[i] <= 4'd0;\n                best_digits[i] <= 4'd0;\n            end\n            cand_len <= 4'd0;\n            best_len <= 4'd0;\n        end else begin\n            case (state)\n                S_IDLE: begin\n                    result_valid <= 1'b0;\n                    if (start) state <= S_LOAD;\n                end\n                \n                S_LOAD: begin\n                    for (i = 0; i < 4; i = i + 1) begin\n                        // Store original data/length\n                        orig_data[i] <= mag_data[i];\n                        orig_len[i] <= mag_len[i];\n                        \n                        // Compute flipped version\n                        flip_valid[i] <= 1'b1;\n                        flip_len[i] <= mag_len[i];\n                        for (j = 0; j < 3; j = j + 1) begin\n                            if (j < mag_len[i]) begin\n                                if (mag_data[i][j*4 +:4] == 0 ||\n                                    mag_data[i][j*4 +:4] == 1 ||\n                                    mag_data[i][j*4 +:4] == 6 ||\n                                    mag_data[i][j*4 +:4] == 8 ||\n                                    mag_data[i][j*4 +:4] == 9) begin\n                                    case (mag_data[i][j*4 +:4])\n                                        4'd6: flip_data[i][(mag_len[i]-1-j)*4 +:4] <= 4'd9;\n                                        4'd9: flip_data[i][(mag_len[i]-1-j)*4 +:4] <= 4'd6;\n                                        default: flip_data[i][(mag_len[i]-1-j)*4 +:4] <= mag_data[i][j*4 +:4];\n                                    endcase\n                                end else begin\n                                    flip_valid[i] <= 1'b0;\n                                end\n                            end\n                        end\n                    end\n                    state <= S_COMB_START;\n                end\n                \n                S_COMB_START: begin\n                    comb <= 4'd0;\n                    best_valid <= 1'b0;\n                    state <= S_COMB_SELECT;\n                end\n                \n                S_COMB_SELECT: begin\n                    for (i = 0; i < 4; i = i + 1) begin\n                        if (comb[i] && flip_valid[i]) begin\n                            sel_data[i] <= flip_data[i];\n                            sel_len[i]  <= flip_len[i];\n                        end else begin\n                            sel_data[i] <= orig_data[i];\n                            sel_len[i]  <= orig_len[i];\n                        end\n                    end\n                    state <= S_SORT;\n                end\n\n                S_SORT: begin\n                    // Simple bubble sort\n                    for (k = 0; k < 4; k = k + 1) begin\n                        for (i = 0; i < 3; i = i + 1) begin\n                            if (!compare_strings(sel_data[i], sel_len[i], sel_data[i+1], sel_len[i+1])) begin\n                                // Swap\n                                sorted_data[i] <= sel_data[i+1];\n                                sorted_len[i] <= sel_len[i+1];\n                                sorted_data[i+1] <= sel_data[i];\n                                sorted_len[i+1] <= sel_len[i];\n                            end else begin\n                                sorted_data[i] <= sel_data[i];\n                                sorted_len[i] <= sel_len[i];\n                                sorted_data[i+1] <= sel_data[i+1];\n                                sorted_len[i+1] <= sel_len[i+1];\n                            end\n                        end\n                    end\n                    state <= S_CONCAT;\n                end\n\n                S_CONCAT: begin\n                    cand_len = 0;\n                    for (i = 0; i < 4; i = i + 1) begin\n                        if (sorted_len[i] > 0) begin\n                            for (j = 0; j < sorted_len[i]; j = j + 1) begin\n                                cand_digits[cand_len] <= sorted_data[i][j*4 +:4];\n                                cand_len = cand_len + 1;\n                            end\n                        end\n                    end\n                    cand_len <= cand_len;\n                    state <= S_COMPARE;\n                end\n\n                S_COMPARE: begin\n                    if (!best_valid || candidate_better()) begin\n                        state <= S_UPDATE;\n                    end else begin\n                        state <= S_NEXT_COMB;\n                    end\n                end\n\n                S_UPDATE: begin\n                    best_len <= cand_len;\n                    for (i = 0; i < 12; i = i + 1) begin\n                        best_digits[i] <= cand_digits[i];\n                    end\n                    best_valid <= 1'b1;\n                    state <= S_NEXT_COMB;\n                end\n\n                S_NEXT_COMB: begin\n                    if (comb == 4'b1111) begin\n                        state <= S_DONE;\n                    end else begin\n                        comb <= comb + 1'b1;\n                        state <= S_COMB_SELECT;\n                    end\n                end\n\n                S_DONE: begin\n                    result_len <= best_len;\n                    for (i = 0; i < 12; i = i + 1) begin\n                        result_digits[i] <= best_digits[i];\n                    end\n                    result_valid <= 1'b1;\n                    state <= S_IDLE;\n                end\n\n                default: state <= S_IDLE;\n            endcase\n        end\n    end\n\n    // Comparison helper function\n    function automatic compare_strings(input [11:0] a, input [1:0] alen, \n                                       input [11:0] b, input [1:0] blen);\n        reg [3:0] ad1, ad2, bd1, bd2;\n        integer i;\n        begin\n            for (i = 0; i < (alen + blen); i = i + 1) begin\n                if (i < alen) ad1 = a[i*4 +:4];\n                else ad1 = 4'd15;\n                if (i < blen) bd1 = b[i*4 +:4];\n                else bd1 = 4'd15;\n\n                if (i < blen) ad2 = b[i*4 +:4];\n                else ad2 = 4'd15;\n                if (i < alen) bd2 = a[i*4 +:4];\n                else bd2 = 4'd15;\n\n                if (ad1 < bd1) begin\n                    compare_strings = 1'b1;\n                    return;\n                end\n                if (ad1 > bd1) begin\n                    compare_strings = 1'b0;\n                    return;\n                end\n\n                if (ad2 < bd2) begin\n                    compare_strings = 1'b0;\n                    return;\n                end\n                if (ad2 > bd2) begin\n                    compare_strings = 1'b1;\n                    return;\n                end\n            end\n            compare_strings = 1'b1;\n        end\n    endfunction\n\n    function automatic candidate_better;\n        integer i;\n        begin\n            if (!best_valid) begin\n                candidate_better = 1'b1;\n                return;\n            end\n            if (cand_len < best_len) begin\n                candidate_better = 1'b1;\n                return;\n            end else if (cand_len > best_len) begin\n                candidate_better = 1'b0;\n                return;\n            end\n            for (i = 0; i < cand_len; i = i + 1) begin\n                if (cand_digits[i] < best_digits[i]) begin\n                    candidate_better = 1'b1;\n                    return;\n                end else if (cand_digits[i] > best_digits[i]) begin\n                    candidate_better = 1'b0;\n                    return;\n                end\n            end\n            candidate_better = 1'b0;\n        end\n    endfunction\n\nendmodule